import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

public class ApplyClaim {
    public void apply(@Val ValidClaim request, @Val Claim claim, Sheets sheets, Periods periods, People people, Claims claims)
            throws InvalidClaimException {
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            // Only a draft can be edited; to change an open claim, void it and add a new one.
            throw new InvalidClaimException("Only a DRAFT claim can be edited");
        }
        String lockedBy = claims.lockedBy(claim);
        if (lockedBy != null && !lockedBy.equals(request.user())) {
            throw new InvalidClaimException("The claim is being edited by " + lockedBy);
        }
        LocalDate date = request.date() != null ? request.date() : sheets.today(claim.getSheetId());
        if (periods.isClosed(claim.getSheetId(), claim.getPeriodDate())) {
            throw new InvalidClaimException("No claim whose due-by is inside a closed period can be edited");
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        if (person != null && !person.allowsClaimOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
        }
        ValidateClaim.checkCorrects(request, claim.getSheetId(), claim.getPersonId(), claims);
        ValidateClaim.checkRef(request.ref(), claim.getSheetId(), claim.getId(), claims);
        claim.setAmount(request.amount());
        claim.setRef(request.ref());
        claim.setCorrects(request.corrects());
        claim.setCorrectedDate(claims.correctedDate(claim.getSheetId(), claim.getPersonId(), request.corrects()));
        claim.setDate(date);
        claim.setNote(request.note());
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class SaveClaimCreated {
    public void save(@Val ValidClaim request, @Val Person person, Claims claims, Sheets sheets, Audit audit, @Val RollupFigures before, Rollup rollup, Periods periods,
            net.officefloor.hq.app.setting.Settings settings, ClaimLog log, net.officefloor.hq.app.holiday.Holidays holidays,
            ObjectResponse<ResponseEntity<ClaimResponse>> response) throws InvalidClaimException {
        String sheetId = person.getSheetId();
        LocalDate date = request.date() != null ? request.date() : settings.claimDate(sheetId);
        LocalDate dueBy = holidays.dueBy(sheetId, date, settings.termsFor(sheetId, person.getTerms(), person.gradeOn(date), date));
        if (periods.isClosed(sheetId, dueBy)) {
            throw new InvalidClaimException("No claim can be added inside a closed period");
        }
        if (!person.allowsClaimOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
        }
        ValidateClaim.checkCorrects(request, sheetId, person.getId(), claims);
        ValidateClaim.checkRef(request.ref(), sheetId, null, claims);
        Claim claim = claims.add(sheetId, person.getId(), request.amount(), date, request.note(), request.corrects(), dueBy, request.ref());
        log.record(claim, person, request.user());
        audit.recordOnCommit(ClaimAudit.added(request.user(), person, claim));
        LateEntry.mark(claim, person, request.user(), claims, periods, audit);
        rollup.recordChanges(sheetId, request.user(), before);
        response.send(new ResponseEntity<>(ClaimResponse.from(claim), HttpStatus.CREATED));
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;

/** amount is shown with two decimals; status is DRAFT, OPEN, PENDING, SETTLED or VOID; number is "" when none;
 *  due is the due fixed when the claim was settled, else (unless PENDING) the figure its person's last statement bound
 *  it to, "" while it is live (or bound to n/a); openedBy is "" when never opened; stated is whether
 *  the last statement bound it; corrects is the number a correction corrects, "" for any other claim;
 *  roundingDate is the date its rounding goes by (a correction's: the date of the claim it corrects);
 *  dueBy is the due-by fixed when the claim was created; log is its status log, oldest first (empty unless listed);
 *  deferredUntil is the date the claim was last deferred until, "" if never; proofs is its proofs count;
 *  splitFrom is the number of the claim a split made it from, "" for any other claim; lockedBy is the user whose
 *  open editor locks it, "" when unlocked; lateEntry is whether it was added while its period was soft-closed;
 *  remindedOn is the last day a reminder was written for it, "" if never; ref is its external reference, "" for none. */
public record ClaimResponse(String id, String personId, String amount, String date, String note, String status,
        String number, String due, String openedBy, boolean stated, String corrects,
        String roundingDate, String dueBy, List<String> log, String deferredUntil, String proofs,
        String splitFrom, String lockedBy, boolean lateEntry, String remindedOn, String ref) {

    public static ClaimResponse from(Claim claim) {
        return new ClaimResponse(String.valueOf(claim.getId()), String.valueOf(claim.getPersonId()),
                claim.getAmount().setScale(2).toPlainString(), claim.getDate().toString(), claim.getNote(),
                claim.getStatus().name(), claim.getNumber() == null ? "" : claim.getNumber(),
                fixedDue(claim) == null ? "" : fixedDue(claim).setScale(2).toPlainString(),
                claim.getOpenedBy() == null ? "" : claim.getOpenedBy(), claim.isStated(),
                claim.getCorrects() == null ? "" : claim.getCorrects(),
                claim.getRoundingDate().toString(), claim.getDueBy().toString(), claim.getLog(),
                claim.getDeferredUntil() == null ? "" : claim.getDeferredUntil().toString(),
                String.valueOf(claim.getProofs()),
                claim.getSplitFrom() == null ? "" : claim.getSplitFrom(),
                claim.getLockedBy() == null ? "" : claim.getLockedBy(), claim.isLateEntry(),
                claim.getRemindedOn() == null ? "" : claim.getRemindedOn().toString(),
                claim.getRef() == null ? "" : claim.getRef());
    }

    /** The due a claim keeps whatever the rates do: fixed when settled, else bound by a statement. */
    public static java.math.BigDecimal fixedDue(Claim claim) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        return claim.isBound() ? claim.getStatedDue() : null;
    }

    public static List<ClaimResponse> from(List<Claim> claims) {
        return claims.stream().map(ClaimResponse::from).toList();
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;

/**
 * The audit line of a claim change: amount as shown (two decimals), date as yyyy-mm-dd, then the
 * claim's number when it has one.
 */
final class ClaimAudit {

    private ClaimAudit() {
    }

    /** CLAIM_ADDED: the line, then ref=<reference> when the claim carries one. */
    static String added(String user, Person person, Claim claim) {
        return line("CLAIM_ADDED", user, person, claim, claim.getNumber()) + (claim.getRef() == null ? "" : " ref=" + claim.getRef());
    }

    static String line(String event, String user, Person person, Claim claim, String number) {
        ClaimResponse shown = ClaimResponse.from(claim);
        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
                + " amount=" + shown.amount() + " date=" + shown.date() + (number == null ? "" : " number=" + number);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/**
 * Splits an amount (more than 0.00, less than the claim's) off an OPEN claim that is not deferred and whose due-by is not inside a
 * closed period; only the roles the sheet's open permission allows split a claim, as the new claim is theirs to open.
 * The claim keeps the rest of its amount and loses any figure a statement bound it to.
 */
public class ApplySplit {
    public void apply(@Val ValidSplit request, @Val Claim claim, Sheets sheets, Periods periods, Settings settings)
            throws ClaimStatusRefusedException {
        if (!settings.allows(claim.getSheetId(), request.user(), "open")) {
            throw new ClaimStatusRefusedException("Your role may not open a claim, so may not split one");
        }
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new ClaimStatusRefusedException("Only an OPEN claim can be split");
        }
        if (claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
            throw new ClaimStatusRefusedException("A deferred claim cannot be split");
        }
        if (periods.isClosed(claim.getSheetId(), claim.getPeriodDate())) {
            throw new ClaimStatusRefusedException("No claim whose due-by is inside a closed period can be split");
        }
        if (request.amount().compareTo(claim.getAmount()) >= 0) {
            throw new ClaimStatusRefusedException("The amount to split off must be less than the claim's amount");
        }
        claim.setAmount(claim.getAmount().subtract(request.amount()));
        claim.setStated(false);
        claim.setStatedDue(null);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Saves the split claim and adds the new OPEN claim with the split-off amount, the same date and note, the next
 *  number, opened by the user, its due-by fixed now from the terms in force on the date, split from the claim, and a
 *  late entry when the claim is one. */
public class SaveSplit {
    public void save(@Val ValidSplit request, @Val Claim claim, Claims claims, People people, Settings settings,
            ClaimNumbering numbering, ClaimLog log, net.officefloor.hq.app.holiday.Holidays holidays, Out<ClaimSplit> split) {
        claims.save(claim);
        claims.bind(claim);
        String sheetId = claim.getSheetId();
        Person person = people.find(sheetId, claim.getPersonId());
        Claim into = claims.add(sheetId, person.getId(), request.amount(), claim.getDate(), claim.getNote(),
                holidays.dueBy(sheetId, claim.getDate(), settings.termsFor(sheetId, person.getTerms(), person.gradeOn(claim.getDate()), claim.getDate())));
        into.setStatus(ClaimStatus.OPEN);
        into.setNumber(numbering.next(sheetId, into.getPeriodDate()));
        into.setOpenedBy(request.user());
        into.setSplitFrom(claim.getNumber());
        claims.save(into);
        claims.splitFrom(into);
        if (claim.isLateEntry()) {
            // A split is judged by the original claim alone: the new claim is a late entry as it is.
            claims.markLateEntry(into);
        }
        log.record(into, person, request.user());
        split.set(new ClaimSplit(into));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The claim store, kept per sheet. */
@Repository
public class Claims {

    private static final RowMapper<Claim> ROW = (rs, i) -> {
        Claim claim = new Claim(rs.getLong("id"), rs.getString("sheet_id"),
                rs.getLong("person_id"), rs.getBigDecimal("amount"), rs.getDate("claim_date").toLocalDate(),
                rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
                rs.getString("claim_number"), rs.getBigDecimal("settled_due"), rs.getString("opened_by"));
        claim.setStated(rs.getBoolean("stated"));
        claim.setStatedDue(rs.getBigDecimal("stated_due"));
        claim.setCorrects(rs.getString("corrects"));
        java.sql.Date corrected = rs.getDate("corrected_date");
        claim.setCorrectedDate(corrected == null ? null : corrected.toLocalDate());
        java.sql.Date dueBy = rs.getDate("due_by");
        claim.setDueBy(dueBy == null ? null : dueBy.toLocalDate());
        java.sql.Date deferredUntil = rs.getDate("deferred_until");
        claim.setDeferredUntil(deferredUntil == null ? null : deferredUntil.toLocalDate());
        java.sql.Date remindedOn = rs.getDate("reminded_on");
        claim.setRemindedOn(remindedOn == null ? null : remindedOn.toLocalDate());
        claim.setProofs(rs.getInt("proofs"));
        claim.setSplitFrom(rs.getString("split_from"));
        claim.setLockedBy(rs.getString("locked_by"));
        claim.setLateEntry(rs.getBoolean("late_entry"));
        claim.setRef(rs.getString("ref"));
        return claim;
    };

    /** A claim with the date of the claim it corrects (same sheet, same person, by number). */
    private static final String SELECT = "SELECT c.*, k.claim_date AS corrected_date FROM claim c LEFT JOIN claim k"
            + " ON k.sheet_id = c.sheet_id AND k.person_id = c.person_id AND k.claim_number = c.corrects";

    /** The listed_seq after every claim's: a new or moved claim is listed first. */
    private static final String NEXT_LISTED = "(SELECT COALESCE(MAX(listed_seq), 0) + 1 FROM claim)";

    private final JdbcTemplate jdbc;

    public Claims(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Records the claim's figure-moving columns as they now stand in its history, dated the sheet's today. */
    private void history(String sheetId, long id) {
        jdbc.update("INSERT INTO claim_history (sheet_id, claim_id, set_on, person_id, amount, claim_date, status, settled_due,"
                + " stated, stated_due, due_by, deferred_until, corrects, claim_number, opened_by, note, proofs, split_from, late_entry)"
                + " SELECT c.sheet_id, c.id, s.today, c.person_id, c.amount, c.claim_date, c.status, c.settled_due, c.stated,"
                + " c.stated_due, c.due_by, c.deferred_until, c.corrects, c.claim_number, c.opened_by, c.note, c.proofs,"
                + " c.split_from, c.late_entry"
                + " FROM claim c JOIN sheet s ON s.id = c.sheet_id WHERE c.sheet_id = ? AND c.id = ?", sheetId, id);
    }

    /** The sheet's claims, newest first. */
    public List<Claim> list(String sheetId) {
        return withLogs(sheetId, jdbc.query(SELECT + " WHERE c.sheet_id = ? ORDER BY c.listed_seq DESC, c.id DESC", ROW, sheetId));
    }

    /** The claims with their status logs (see {@link ClaimLog}), oldest line first. */
    private List<Claim> withLogs(String sheetId, List<Claim> claims) {
        Map<Long, List<String>> logs = new HashMap<>();
        jdbc.query("SELECT claim_id, status, by_user, log_date, due FROM claim_log WHERE sheet_id = ? ORDER BY id", rs -> {
            logs.computeIfAbsent(rs.getLong("claim_id"), id -> new ArrayList<>())
                    .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
                            + rs.getDate("log_date").toLocalDate() + " due=" + rs.getString("due"));
        }, sheetId);
        claims.forEach(claim -> claim.setLog(logs.getOrDefault(claim.getId(), List.of())));
        return claims;
    }

    /** A person's claims on the sheet, newest first. */
    public List<Claim> ofPerson(String sheetId, long personId) {
        return jdbc.query(SELECT + " WHERE c.sheet_id = ? AND c.person_id = ? ORDER BY c.listed_seq DESC, c.id DESC", ROW, sheetId, personId);
    }

    public Claim find(String sheetId, long id) {
        List<Claim> found = jdbc.query(SELECT + " WHERE c.sheet_id = ? AND c.id = ?", ROW, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, LocalDate dueBy) {
        return add(sheetId, personId, amount, date, note, null, dueBy);
    }

    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            LocalDate dueBy) {
        return add(sheetId, personId, amount, date, note, corrects, dueBy, null);
    }

    /** Adds a DRAFT claim with its due-by fixed as given, and its external reference (null for none). */
    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            LocalDate dueBy, String ref) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, due_by, ref, listed_seq) VALUES (?, ?, ?, ?, ?, ?, ?, ?, "
                            + NEXT_LISTED + ")",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, sheetId);
            ps.setLong(2, personId);
            ps.setBigDecimal(3, amount);
            ps.setDate(4, Date.valueOf(date));
            ps.setString(5, note);
            ps.setString(6, corrects);
            ps.setDate(7, Date.valueOf(dueBy));
            ps.setString(8, ref);
            return ps;
        }, keys);
        Claim claim = new Claim(keys.getKey().longValue(), sheetId, personId, amount, date, note, ClaimStatus.DRAFT, null, null, null);
        history(sheetId, claim.getId());
        claim.setCorrects(corrects);
        claim.setDueBy(dueBy);
        claim.setRef(ref);
        claim.setCorrectedDate(correctedDate(sheetId, personId, corrects));
        return claim;
    }

    /** Whether a claim on the sheet (other than exceptId, when given) carries the reference, compared without regard to case. */
    public boolean refUsed(String sheetId, String ref, Long exceptId) {
        Integer found = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND LOWER(ref) = LOWER(?) AND id <> ?",
                Integer.class, sheetId, ref, exceptId == null ? -1L : exceptId);
        return found != null && found > 0;
    }

    /** The date of the person's claim with this number; null when there is none (or no number). */
    public LocalDate correctedDate(String sheetId, long personId, String number) {
        if (number == null) return null;
        List<LocalDate> found = jdbc.query("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ? AND claim_number = ?",
                (rs, i) -> rs.getDate(1).toLocalDate(), sheetId, personId, number);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Bind the claim to the figure a statement gives it (stated), or leave it unbound. */
    public void bind(Claim claim) {
        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet_id = ? AND id = ?",
                claim.isStated(), claim.getStatedDue(), claim.getSheetId(), claim.getId());
        history(claim.getSheetId(), claim.getId());
    }

    /** Whether the person has a SETTLED claim with this number on the sheet: one a correction may correct. */
    public boolean isSettled(String sheetId, long personId, String number) {
        Integer found = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ?"
                + " AND claim_number = ? AND status = ?", Integer.class, sheetId, personId, number, ClaimStatus.SETTLED.name());
        return found != null && found > 0;
    }

    /** Moves the claim to its (new) person, listed as their newest claim, and leaves it unbound. */
    public void reassign(Claim claim) {
        jdbc.update("UPDATE claim SET person_id = ?, stated = ?, stated_due = ?, listed_seq = " + NEXT_LISTED
                + " WHERE sheet_id = ? AND id = ?", claim.getPersonId(), claim.isStated(), claim.getStatedDue(),
                claim.getSheetId(), claim.getId());
        history(claim.getSheetId(), claim.getId());
    }

    /** Records the claim's reminded date. */
    public void remind(Claim claim) {
        jdbc.update("UPDATE claim SET reminded_on = ? WHERE sheet_id = ? AND id = ?",
                Date.valueOf(claim.getRemindedOn()), claim.getSheetId(), claim.getId());
    }

    /** Defers the claim until its deferred-until date. */
    public void defer(Claim claim) {
        jdbc.update("UPDATE claim SET deferred_until = ? WHERE sheet_id = ? AND id = ?",
                Date.valueOf(claim.getDeferredUntil()), claim.getSheetId(), claim.getId());
        history(claim.getSheetId(), claim.getId());
    }

    /** Records the claim's (new) date and number. */
    public void redate(Claim claim) {
        jdbc.update("UPDATE claim SET claim_date = ?, claim_number = ? WHERE sheet_id = ? AND id = ?",
                Date.valueOf(claim.getDate()), claim.getNumber(), claim.getSheetId(), claim.getId());
        history(claim.getSheetId(), claim.getId());
    }

    /** Marks the claim a late entry: added while its period was soft-closed. */
    public void markLateEntry(Claim claim) {
        claim.setLateEntry(true);
        jdbc.update("UPDATE claim SET late_entry = TRUE WHERE sheet_id = ? AND id = ?", claim.getSheetId(), claim.getId());
        history(claim.getSheetId(), claim.getId());
    }

    /** Records the number of the claim this claim was split from. */
    public void splitFrom(Claim claim) {
        jdbc.update("UPDATE claim SET split_from = ? WHERE sheet_id = ? AND id = ?",
                claim.getSplitFrom(), claim.getSheetId(), claim.getId());
        history(claim.getSheetId(), claim.getId());
    }

    /** Records the claim's proofs count. */
    /** Who holds the claim's editor lock; null when unlocked. */
    public String lockedBy(Claim claim) {
        List<String> found = jdbc.query("SELECT locked_by FROM claim WHERE sheet_id = ? AND id = ?",
                (rs, i) -> rs.getString(1), claim.getSheetId(), claim.getId());
        return found.isEmpty() ? null : found.get(0);
    }

    public void lock(Claim claim, String user) {
        claim.setLockedBy(user);
        jdbc.update("UPDATE claim SET locked_by = ? WHERE sheet_id = ? AND id = ?", user, claim.getSheetId(), claim.getId());
    }

    public void unlock(Claim claim) {
        claim.setLockedBy(null);
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND id = ?", claim.getSheetId(), claim.getId());
    }

    /** Releases every claim's lock on the sheet (its today changed). */
    public void unlockAll(String sheetId) {
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND locked_by IS NOT NULL", sheetId);
    }

    public void proofs(Claim claim) {
        jdbc.update("UPDATE claim SET proofs = ? WHERE sheet_id = ? AND id = ?",
                claim.getProofs(), claim.getSheetId(), claim.getId());
        history(claim.getSheetId(), claim.getId());
    }

    public void save(Claim claim) {
        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, claim_number = ?, settled_due = ?, opened_by = ?, corrects = ?, ref = ? WHERE sheet_id = ? AND id = ?",
                claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
                claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(), claim.getCorrects(), claim.getRef(),
                claim.getSheetId(), claim.getId());
        history(claim.getSheetId(), claim.getId());
    }
}

